// ── Observable store (push model) ───────────────────────────────
class EventEmitter {
  constructor() { this._listeners = {}; }

  on(event, fn) {
    if (!this._listeners[event]) this._listeners[event] = [];
    this._listeners[event].push(fn);
    return () => this.off(event, fn); // returns unsubscribe fn
  }

  off(event, fn) {
    this._listeners[event] = (this._listeners[event] || []).filter(l => l !== fn);
  }

  emit(event, data) {
    (this._listeners[event] || []).forEach(fn => fn(data));
  }
}

class SalesStore extends EventEmitter {
  constructor() {
    super();
    this._state = { sales: 0, region: 'APAC' };
  }

  getState() { return { ...this._state }; }

  setSales(amount) {
    this._state = { ...this._state, sales: amount };
    this.emit('change', this.getState()); // notify all observers
  }
}

// ── Observers ────────────────────────────────────────────────────
const store = new SalesStore();

const chartObserver = (state) =>
  console.log(`[Chart] Rendering bar at ${state.sales} for ${state.region}`);

const logObserver = (state) =>
  console.log(`[Log]   State updated:`, JSON.stringify(state));

const unsubChart = store.on('change', chartObserver);
const unsubLog   = store.on('change', logObserver);

store.setSales(42);
// [Chart] Rendering bar at 42 for APAC
// [Log]   State updated: {"sales":42,"region":"APAC"}

unsubLog(); // remove log observer

store.setSales(99);
// [Chart] Rendering bar at 99 for APAC  ← only chart fires

console.log('Done.');

// ── Minimal Observer skeleton ────────────────────────────────────
class Subject {
  constructor() { this._observers = []; }
  subscribe(obs)   { this._observers.push(obs); }
  unsubscribe(obs) { this._observers = this._observers.filter(o => o !== obs); }
  notify(data)     { this._observers.forEach(o => o.update(data)); }
}

class Observer {
  update(data) { throw new Error('update() must be implemented'); }
}

// ── Concrete participants ────────────────────────────────────────
class TemperatureSensor extends Subject {
  setTemperature(temp) {
    console.log(`Sensor: temp = ${temp}°C`);
    this.notify({ temp });
  }
}

class AlarmDisplay extends Observer {
  update({ temp }) {
    if (temp > 80) console.log('ALARM: Overheat!');
    else console.log(`Display: ${temp}°C — OK`);
  }
}

class DataLogger extends Observer {
  update({ temp }) { console.log(`Logger: recorded ${temp}°C`); }
}

const sensor  = new TemperatureSensor();
const alarm   = new AlarmDisplay();
const logger  = new DataLogger();

sensor.subscribe(alarm);
sensor.subscribe(logger);
sensor.setTemperature(70);
sensor.setTemperature(95);
